import math

# Registry data - most precise values available
data = {
    'uniform': {
        'seed42': {
            'holdout': 13.280, 'owt': 13.291, 'wiki': 10.919,
            'arc_easy': 0.7235, 'arc_challenge': 0.4334, 'hellaswag': 0.6107,
            'piqa': 0.7432, 'winogrande': 0.6172, 'ds_mean': 0.6256
        },
        'seed123': {
            'holdout': 13.2648, 'owt': 13.2918, 'wiki': 10.942,
            'arc_easy': 0.726, 'arc_challenge': 0.4317, 'hellaswag': 0.6118,
            'piqa': 0.7454, 'winogrande': 0.6133, 'ds_mean': 0.6256
        }
    },
    'adaptive': {
        'seed42': {
            'holdout': 13.270, 'owt': 13.282, 'wiki': 10.955,
            'arc_easy': 0.7176, 'arc_challenge': 0.4403, 'hellaswag': 0.6164,
            'piqa': 0.7443, 'winogrande': 0.6069, 'ds_mean': 0.6251
        },
        'seed123': {
            'holdout': 13.250, 'owt': 13.2909, 'wiki': 10.9521,
            'arc_easy': 0.7138, 'arc_challenge': 0.4386, 'hellaswag': 0.6147,
            'piqa': 0.7459, 'winogrande': 0.6298, 'ds_mean': 0.6286
        }
    }
}

def mean_std(vals):
    m = sum(vals) / len(vals)
    if len(vals) < 2:
        return m, 0
    s = math.sqrt(sum((v-m)**2 for v in vals) / (len(vals)-1))
    return m, s

metrics = ['holdout', 'owt', 'wiki', 'ds_mean']
labels = {'holdout': 'Holdout PPL', 'owt': 'OWT PPL', 'wiki': 'Wiki PPL', 'ds_mean': 'DS Mean'}

for metric in metrics:
    u_vals = [data['uniform']['seed42'][metric], data['uniform']['seed123'][metric]]
    a_vals = [data['adaptive']['seed42'][metric], data['adaptive']['seed123'][metric]]
    u_m, u_s = mean_std(u_vals)
    a_m, a_s = mean_std(a_vals)
    deltas = [a-u for a, u in zip(a_vals, u_vals)]
    d_m, d_s = mean_std(deltas)
    print(f'{labels[metric]}:')
    print(f'  Uniform: {u_m:.4f} ± {u_s:.4f}  [{u_vals[0]:.4f}, {u_vals[1]:.4f}]')
    print(f'  Adaptive: {a_m:.4f} ± {a_s:.4f}  [{a_vals[0]:.4f}, {a_vals[1]:.4f}]')
    print(f'  Δ(A-U): {d_m:+.4f} ± {d_s:.4f}  [s42: {deltas[0]:+.4f}, s123: {deltas[1]:+.4f}]')
    print()

# DS breakdown
ds_metrics = ['arc_easy', 'arc_challenge', 'hellaswag', 'piqa', 'winogrande']
print('\\nDownstream breakdown:')
for dm in ds_metrics:
    u_vals = [data['uniform']['seed42'][dm], data['uniform']['seed123'][dm]]
    a_vals = [data['adaptive']['seed42'][dm], data['adaptive']['seed123'][dm]]
    u_m, u_s = mean_std(u_vals)
    a_m, a_s = mean_std(a_vals)
    d = a_m - u_m
    print(f'  {dm}: U={u_m:.4f}±{u_s:.4f}, A={a_m:.4f}±{a_s:.4f}, Δ={d:+.4f}')
"
